#!/usr/bin/env bash
set -euo pipefail
# TEST ONLY. Creates a disposable, network-none MySQL 8.4 schema. No RPC,
# wallet, server, deployment or production credential is accepted or used.
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
IMAGE='mysql@sha256:c831a0f11348d402b43d77453e17d770be2eef356615a2823fe0f5a0d6c8b9af'
SOCKET='/var/run/docker.sock'; RUN_ID="$(uuidgen | tr '[:upper:]' '[:lower:]')"; RUN_HEX="${RUN_ID//-/}"
NAME="jc-fl-mainnet-activation-schema-$RUN_HEX"; LABEL_KEY='joincare.fair-launch.mainnet-activation-schema-test'
DB="jc_fl_ma_${RUN_HEX}"; SECRET_DIR=''; CONTAINER_ID=''; OUTPUT="/tmp/jc-fl-mainnet-activation-$RUN_HEX.out"
fail(){ echo "fair_launch_mysql8_mainnet_activation_schema_test: FAIL: $*" >&2; exit 1; }
docker_local(){ docker -H "unix://$SOCKET" "$@"; }
cleanup(){ if [ -n "$CONTAINER_ID" ]; then observed="$(docker_local inspect --format "{{index .Config.Labels \"$LABEL_KEY\"}}" "$CONTAINER_ID" 2>/dev/null || true)"; [ "$observed" != "$RUN_ID" ] || docker_local rm -f "$CONTAINER_ID" >/dev/null 2>&1 || true; fi; [ -z "$SECRET_DIR" ] || rm -rf "$SECRET_DIR"; rm -f "$OUTPUT"; }
for forbidden in JC_DEPLOY_RPC JC_DEPLOY_CHAIN_ID JC_DEPLOY_PRIVATE_KEY JC_MYSQL_ROOT_PASSWORD MYSQL_PWD FAIR_LAUNCH_DISPOSABLE_MYSQL_DSN DOCKER_HOST DOCKER_CONTEXT DOCKER_TLS_VERIFY DOCKER_CERT_PATH; do [ -z "${!forbidden:-}" ] || fail "refusing external/production environment: $forbidden"; done
command -v docker >/dev/null || fail 'docker required'; command -v openssl >/dev/null || fail 'openssl required'; command -v sha256sum >/dev/null || fail 'sha256sum required'; [ -S "$SOCKET" ] || fail 'local Docker Unix socket unavailable'; [ "$(readlink -f "$SOCKET")" = '/run/docker.sock' ] || fail 'unexpected Docker socket'
docker_local version >/dev/null 2>&1 || fail 'local Docker daemon unavailable'; docker_local image inspect "$IMAGE" >/dev/null 2>&1 || fail 'pinned MySQL image unavailable locally'; trap cleanup EXIT INT TERM
umask 077; SECRET_DIR="$(mktemp -d)"; openssl rand -hex 32 > "$SECRET_DIR/root"; chmod 600 "$SECRET_DIR/root"
CONTAINER_ID="$(docker_local run -d --name "$NAME" --label "$LABEL_KEY=$RUN_ID" --network none --tmpfs /var/lib/mysql:rw,nosuid,nodev,size=2g --tmpfs /tmp:rw,nosuid,nodev,size=256m -v "$SECRET_DIR/root:/run/secrets/root:ro" -v "$ROOT:/repo:ro" -e MYSQL_ROOT_PASSWORD_FILE=/run/secrets/root "$IMAGE" --skip-log-bin --local-infile=OFF --secure-file-priv=NULL)"
[ "$(docker_local inspect --format "{{index .Config.Labels \"$LABEL_KEY\"}}" "$CONTAINER_ID")" = "$RUN_ID" ] || fail 'container ownership mismatch'
docker_local exec "$CONTAINER_ID" sh -c 'umask 077; { echo "[client]"; echo "user=root"; printf "password="; cat /run/secrets/root; echo "host=127.0.0.1"; echo "protocol=tcp"; } >/tmp/root.cnf; chmod 600 /tmp/root.cnf'
for _ in $(seq 1 90); do docker_local exec "$CONTAINER_ID" mysqladmin --defaults-extra-file=/tmp/root.cnf ping --silent >/dev/null 2>&1 && break; sleep 1; done
docker_local exec "$CONTAINER_ID" mysqladmin --defaults-extra-file=/tmp/root.cnf ping --silent >/dev/null || fail 'MySQL not ready'
mysql_root(){ docker_local exec -i "$CONTAINER_ID" mysql --defaults-extra-file=/tmp/root.cnf --batch --raw --skip-column-names "$@"; }; mysql_db(){ mysql_root "$DB"; }; query(){ printf '%s\n' "$1" | mysql_db | tr -d '\r'; }; assert_eq(){ [ "$2" = "$3" ] || fail "$1 got=$2 want=$3"; }; expect_fail(){ local message="$1"; shift; set +e; "$@" >"$OUTPUT" 2>&1; local rc=$?; set -e; [ "$rc" -ne 0 ] && grep -Fq "$message" "$OUTPUT" || fail "expected rejection: $message"; }
(cd "$ROOT/migrations" && sha256sum -c FAIR_LAUNCH_SHA256SUMS); assert_eq 'MySQL version' "$(printf 'SELECT VERSION();\n'|mysql_root)" '8.4.10'
printf 'CREATE DATABASE `%s` CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;\n' "$DB" | mysql_root
printf '%s\n' "CREATE TABLE schema_migrations(filename VARCHAR(255) PRIMARY KEY,checksum CHAR(64) NOT NULL,status VARCHAR(16) NOT NULL,applied_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;" | mysql_db
while read -r checksum marked; do file="${marked#\*}"; printf "INSERT INTO schema_migrations VALUES('%s','%s','applied',NOW(6));\n" "$file" "$checksum" | mysql_db; done < "$ROOT/migrations/baseline/fair-launch-pre-2026-09-03-ledger.sha256"
mysql_db < "$ROOT/migrations/baseline/fair-launch-pre-2026-09-03.sql"
FROZEN=(2026_09_03_fair_launch_project_model.sql 2026_09_04_fair_launch_ce_v2_governance.sql 2026_09_05_fair_launch_signing_release_control.sql 2026_09_06_fair_launch_action_execution.sql 2026_09_07_fair_launch_position_projection.sql)
LOCAL=(2026_09_08_fair_launch_local_e2e_binding.sql 2026_09_09_fair_launch_financial_projection_v3.sql 2026_09_10_fair_launch_governance_projection_v3.sql 2026_09_11_fair_launch_effect_lineage_v3.sql 2026_09_12_fair_launch_typed_ledger_v3.sql)
for f in "${FROZEN[@]}"; do { echo 'SET @JC_FAIR_LAUNCH_MIGRATION_APPROVED=1;'; cat "$ROOT/migrations/$f"; } | mysql_db; done
for f in "${LOCAL[@]}"; do { echo 'SET @JC_FAIR_LAUNCH_LOCAL_E2E_APPROVED=1;'; printf "SET @JC_FAIR_LAUNCH_LOCAL_E2E_RUN_ID='%s';\n" "$RUN_ID"; cat "$ROOT/migrations/$f"; } | mysql_db; done

# Seed a pre-0913 local authority to prove identity-preserving backfill.
cat <<SQL | mysql_db
INSERT INTO fair_launch_local_e2e_run(run_id,environment,exact_rpc_url,redis_endpoint,chain_id,database_name,mysql_server_uuid,mysql_version,container_id,owner_label_digest,schema_generation,baseline_digest,migration_manifest_digest,schema_digest,grant_digest,source_registry_digest,hardhat_genesis_hash,chain_manifest_digest,deployment_manifest_digest,runtime_admission_digest,created_at,expires_at,state) VALUES('$RUN_ID','local-e2e','http://127.0.0.1:18545','127.0.0.1:16379',31337,'$DB','00000000-0000-0000-0000-000000000001','8.4.10','$CONTAINER_ID',REPEAT('a',64),12,REPEAT('b',64),REPEAT('c',64),REPEAT('d',64),REPEAT('e',64),REPEAT('f',64),CONCAT('0x',REPEAT('1',64)),REPEAT('2',64),REPEAT('3',64),REPEAT('4',64),NOW(6),DATE_ADD(NOW(6),INTERVAL 1 HOUR),'verified');
SQL
LOCAL_ROW_ID="$(query "SELECT id FROM fair_launch_local_e2e_run WHERE run_id='$RUN_ID';")"
expect_fail 'explicit execution gate' mysql_db < "$ROOT/migrations/2026_09_13_fair_launch_bsc_mainnet_activation.sql"
{ echo 'SET @JC_FAIR_LAUNCH_MAINNET_ACTIVATION_APPROVED=1;'; cat "$ROOT/migrations/2026_09_13_fair_launch_bsc_mainnet_activation.sql"; } | mysql_db
assert_eq 'local authority ID preserved' "$(query "SELECT id FROM fair_launch_authority_v1 WHERE authority_kind='local_e2e' AND authority_identity='$RUN_ID';")" "$LOCAL_ROW_ID"
assert_eq 'local authority chain preserved' "$(query "SELECT CONCAT(environment,'/',chain_id) FROM fair_launch_authority_v1 WHERE id=$LOCAL_ROW_ID;")" 'local-e2e/31337'
assert_eq 'activation rows remain zero after migration' "$(query 'SELECT COUNT(*) FROM fair_launch_mainnet_activation_v1;')" '0'
assert_eq 'authority parent FK count' "$(query "SELECT COUNT(*) FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME='fair_launch_authority_v1' AND CONSTRAINT_NAME LIKE 'fk_fl_%authority';")" '13'
assert_eq 'chain checks admit only two chains' "$(query "SELECT COUNT(*) FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND CONSTRAINT_NAME IN('chk_fl_source_binding','chk_fl_project_binding','chk_fl_project_state','chk_fl_position_v3','chk_fl_gov_current','chk_fl_gov_history','chk_fl_policy_current','chk_fl_policy_history','chk_fl_lineage','chk_fl_reversal_guard','chk_fl_effect_guard','chk_fl_journal','chk_fl_dependency','chk_fl_attestation','chk_fl_cursor_checkpoint','chk_fl_ledger_v3','chk_fl_source_token_binding','chk_fl_gov_ledger_v3') AND CHECK_CLAUSE LIKE '%31337%' AND CHECK_CLAUSE LIKE '%56%';")" '18'
POST_LOCAL_RUN_ID="$(uuidgen | tr '[:upper:]' '[:lower:]')"
cat <<SQL | mysql_db
INSERT INTO fair_launch_local_e2e_run(run_id,environment,exact_rpc_url,redis_endpoint,chain_id,database_name,mysql_server_uuid,mysql_version,container_id,owner_label_digest,schema_generation,baseline_digest,migration_manifest_digest,schema_digest,grant_digest,source_registry_digest,hardhat_genesis_hash,chain_manifest_digest,deployment_manifest_digest,runtime_admission_digest,created_at,expires_at,state) VALUES('$POST_LOCAL_RUN_ID','local-e2e','http://127.0.0.1:28545','127.0.0.1:26379',31337,'${DB}_post','00000000-0000-0000-0000-000000000002','8.4.10',REPEAT('9',64),REPEAT('a',64),12,REPEAT('b',64),REPEAT('c',64),REPEAT('d',64),REPEAT('e',64),REPEAT('f',64),CONCAT('0x',REPEAT('1',64)),REPEAT('2',64),REPEAT('3',64),REPEAT('4',64),NOW(6),DATE_ADD(NOW(6),INTERVAL 1 HOUR),'verified');
SQL
assert_eq 'post-0913 local child parent allocation' "$(query "SELECT CONCAT(r.id,'/',a.id,'/',a.authority_kind,'/',a.chain_id) FROM fair_launch_local_e2e_run r JOIN fair_launch_authority_v1 a ON a.id=r.id AND a.chain_id=r.chain_id WHERE r.run_id='$POST_LOCAL_RUN_ID';")" "$(query "SELECT CONCAT(id,'/',id,'/local_e2e/31337') FROM fair_launch_local_e2e_run WHERE run_id='$POST_LOCAL_RUN_ID';")"

# Exact test-server source/revision and activation; still no wallet/service enablement.
cat <<'SQL' | mysql_db
INSERT INTO chain_contract_source(id,chain_id,contract_address,contract_version,funding_mode,registered_at,start_block,enabled) VALUES(560001,56,'0x1111111111111111111111111111111111111111','fair_launch_v1','fair_launch',NOW(6),100,1);
INSERT INTO chain_contract_source_revision(id,source_id,revision_no,activation_block_hash,proxy_kind,abi_digest,confirmation_policy,governance_tx_hash,governance_operation_id,implementation_address,implementation_code_hash,dependency_manifest_digest,abi_version,from_block_number,from_transaction_index,from_tx_log_ordinal_inclusive,created_at) VALUES(560002,560001,1,CONCAT('0x',REPEAT('1',64)),'uups',REPEAT('2',64),'20_blocks',CONCAT('0x',REPEAT('3',64)),CONCAT('0x',REPEAT('4',64)),'0x2222222222222222222222222222222222222222',REPEAT('5',64),REPEAT('6',64),'fair-launch-v1',100,0,0,NOW(6));
SQL
ACTIVATION_ID="$(uuidgen | tr '[:upper:]' '[:lower:]')"
activation_insert="INSERT INTO fair_launch_mainnet_activation_v1(activation_id,environment,chain_id,rpc_genesis_hash,rpc_identity_digest,proxy_address,proxy_runtime_code_hash,implementation_address,implementation_code_hash,abi_digest,source_id,source_revision_id,source_start_block,source_start_block_hash,source_registry_digest,payment_token_allowlist_digest,project_allowlist_digest,release_manifest_digest,migration_manifest_digest,activation_manifest_digest,signing_key_id,signature_digest,governance_evidence_digest,valid_from,valid_until,created_at) VALUES('$ACTIVATION_ID','test-server',56,CONCAT('0x',REPEAT('0',64)),REPEAT('1',64),'0x1111111111111111111111111111111111111111',REPEAT('7',64),'0x2222222222222222222222222222222222222222',REPEAT('5',64),REPEAT('2',64),560001,560002,100,CONCAT('0x',REPEAT('1',64)),REPEAT('8',64),REPEAT('9',64),REPEAT('a',64),REPEAT('b',64),REPEAT('c',64),REPEAT('d',64),'test-key-1',REPEAT('e',64),REPEAT('f',64),DATE_ADD(NOW(6),INTERVAL 1 SECOND),DATE_ADD(NOW(6),INTERVAL 1 HOUR),NOW(6));"
printf '%s\n' "$activation_insert" | mysql_db
ACTIVATION_ROW_ID="$(query "SELECT authority_row_id FROM fair_launch_mainnet_activation_v1 WHERE activation_id='$ACTIVATION_ID';")"
assert_eq 'mainnet authority exact identity' "$(query "SELECT CONCAT(a.authority_kind,'/',a.environment,'/',a.chain_id) FROM fair_launch_authority_v1 a WHERE a.id=$ACTIVATION_ROW_ID;")" 'test_server_bsc_mainnet/test-server/56'
expect_fail 'Fair Launch mainnet activation source identity mismatch' mysql_db <<SQL
INSERT INTO fair_launch_mainnet_activation_v1(activation_id,environment,chain_id,rpc_genesis_hash,rpc_identity_digest,proxy_address,proxy_runtime_code_hash,implementation_address,implementation_code_hash,abi_digest,source_id,source_revision_id,source_start_block,source_start_block_hash,source_registry_digest,payment_token_allowlist_digest,project_allowlist_digest,release_manifest_digest,migration_manifest_digest,activation_manifest_digest,signing_key_id,signature_digest,governance_evidence_digest,valid_from,valid_until,created_at) VALUES('$(uuidgen | tr '[:upper:]' '[:lower:]')','test-server',56,CONCAT('0x',REPEAT('0',64)),REPEAT('1',64),'0x3333333333333333333333333333333333333333',REPEAT('7',64),'0x2222222222222222222222222222222222222222',REPEAT('5',64),REPEAT('2',64),560001,560002,100,CONCAT('0x',REPEAT('1',64)),REPEAT('8',64),REPEAT('9',64),REPEAT('a',64),REPEAT('b',64),REPEAT('c',64),REPEAT('d',64),'test-key-1',REPEAT('e',64),REPEAT('f',64),DATE_ADD(NOW(6),INTERVAL 1 SECOND),DATE_ADD(NOW(6),INTERVAL 1 HOUR),NOW(6));
SQL
expect_fail 'Check constraint' mysql_db <<SQL
INSERT INTO fair_launch_mainnet_payment_token_v1(activation_row_id,chain_id,token_symbol,token_address,token_decimals,runtime_code_hash,policy_digest,policy_version,max_activation_value_raw,binding_digest,created_at) VALUES($ACTIVATION_ROW_ID,56,'USDT','0x55d398326f99059ff775485246999027b3197955',6,REPEAT('1',64),REPEAT('2',64),1,'1000000',REPEAT('3',64),NOW(6));
SQL
printf "INSERT INTO fair_launch_mainnet_payment_token_v1(activation_row_id,chain_id,token_symbol,token_address,token_decimals,runtime_code_hash,policy_digest,policy_version,max_activation_value_raw,binding_digest,created_at) VALUES(%s,56,'USDT','0x55d398326f99059ff775485246999027b3197955',18,REPEAT('1',64),REPEAT('2',64),1,'1000000000000000000',REPEAT('3',64),NOW(6));\n" "$ACTIVATION_ROW_ID" | mysql_db
TEST_PROJECT_ID="$(query 'SELECT MIN(project_id) FROM projects;')"; [ -n "$TEST_PROJECT_ID" ] || fail 'baseline has no project row for binding test'
cat <<SQL | mysql_db
INSERT INTO fair_launch_source_revision_binding_v3(run_row_id,chain_id,source_id,source_revision_id,from_block_number,from_transaction_index,from_tx_log_ordinal_inclusive,source_binding_digest,created_at) VALUES($ACTIVATION_ROW_ID,56,560001,560002,100,0,0,REPEAT('1',64),NOW(6));
INSERT INTO fair_launch_mainnet_project_admission_v1(activation_row_id,chain_id,project_row_id,project_id,payment_token_address,payment_token_decimals,project_token_address,project_token_decimals,project_token_runtime_code_hash,max_total_contribution_raw,max_wallet_contribution_raw,admission_digest,created_at) SELECT $ACTIVATION_ROW_ID,56,id,project_id,'0x55d398326f99059ff775485246999027b3197955',18,'0x4444444444444444444444444444444444444444',18,REPEAT('4',64),'1000000000000000000','100000000000000000',REPEAT('5',64),NOW(6) FROM projects WHERE project_id=$TEST_PROJECT_ID;
INSERT INTO fair_launch_project_binding_v3(run_row_id,project_row_id,chain_id,contract_address,contract_version,project_id,project_id_raw,source_binding_id,source_id,source_revision_id,project_token_address,project_token_decimals,payment_token_address,payment_token_decimals,binding_digest,created_at) SELECT $ACTIVATION_ROW_ID,p.id,56,'0x1111111111111111111111111111111111111111','fair_launch_v1',p.project_id,CAST(p.project_id AS CHAR),s.id,560001,560002,'0x4444444444444444444444444444444444444444',18,'0x55d398326f99059ff775485246999027b3197955',18,REPEAT('6',64),NOW(6) FROM projects p JOIN fair_launch_source_revision_binding_v3 s ON s.run_row_id=$ACTIVATION_ROW_ID AND s.chain_id=56 WHERE p.project_id=$TEST_PROJECT_ID;
INSERT INTO fair_launch_source_token_binding_v3(run_row_id,chain_id,source_id,contract_address,token_address,token_decimals,metadata_version,admission_generation,runtime_code_hash,metadata_digest,admitted_at) VALUES($ACTIVATION_ROW_ID,56,560001,'0x1111111111111111111111111111111111111111','0x55d398326f99059ff775485246999027b3197955',18,1,1,REPEAT('1',64),REPEAT('7',64),NOW(6)),($ACTIVATION_ROW_ID,56,560001,'0x1111111111111111111111111111111111111111','0x4444444444444444444444444444444444444444',18,1,1,REPEAT('4',64),REPEAT('8',64),NOW(6));
INSERT INTO fair_launch_mainnet_activation_history_v1(activation_row_id,chain_id,sequence_no,previous_state,state,previous_entry_digest,entry_digest,evidence_digest,created_at) VALUES($ACTIVATION_ROW_ID,56,1,NULL,'prepared',NULL,REPEAT('9',64),REPEAT('a',64),NOW(6)),($ACTIVATION_ROW_ID,56,2,'prepared','admitted',REPEAT('9',64),REPEAT('b',64),REPEAT('c',64),NOW(6));
SQL
assert_eq 'admitted mainnet bindings' "$(query "SELECT CONCAT((SELECT COUNT(*) FROM fair_launch_source_revision_binding_v3 WHERE run_row_id=$ACTIVATION_ROW_ID AND chain_id=56),'/',(SELECT COUNT(*) FROM fair_launch_project_binding_v3 WHERE run_row_id=$ACTIVATION_ROW_ID AND chain_id=56),'/',(SELECT COUNT(*) FROM fair_launch_source_token_binding_v3 WHERE run_row_id=$ACTIVATION_ROW_ID AND chain_id=56));")" '1/1/2'
expect_fail 'invalid Fair Launch mainnet activation transition' mysql_db <<SQL
INSERT INTO fair_launch_mainnet_activation_history_v1(activation_row_id,chain_id,sequence_no,previous_state,state,previous_entry_digest,entry_digest,evidence_digest,created_at) VALUES($ACTIVATION_ROW_ID,56,3,'admitted','wallet_enabled',REPEAT('b',64),REPEAT('d',64),REPEAT('e',64),NOW(6));
SQL
expect_fail 'Fair Launch mainnet project binding is not admitted' mysql_db <<SQL
INSERT INTO fair_launch_project_binding_v3(run_row_id,project_row_id,chain_id,contract_address,contract_version,project_id,project_id_raw,source_binding_id,source_id,source_revision_id,project_token_address,project_token_decimals,payment_token_address,payment_token_decimals,binding_digest,created_at) SELECT $ACTIVATION_ROW_ID,p.id,56,'0x1111111111111111111111111111111111111111','fair_launch_v1',p.project_id,CAST(p.project_id AS CHAR),s.id,560001,560002,'0x5555555555555555555555555555555555555555',18,'0x55d398326f99059ff775485246999027b3197955',18,REPEAT('1',64),NOW(6) FROM projects p JOIN fair_launch_source_revision_binding_v3 s ON s.run_row_id=$ACTIVATION_ROW_ID AND s.chain_id=56 WHERE p.project_id=$TEST_PROJECT_ID;
SQL
expect_fail 'Check constraint' mysql_db <<SQL
INSERT INTO fair_launch_source_revision_binding_v3(run_row_id,chain_id,source_id,source_revision_id,from_block_number,from_transaction_index,from_tx_log_ordinal_inclusive,source_binding_digest,created_at) VALUES($ACTIVATION_ROW_ID,57,560001,560002,100,0,0,REPEAT('1',64),NOW(6));
SQL
echo "fair_launch_mysql8_mainnet_activation_schema_test: PASS run_id=$RUN_ID container_id=$CONTAINER_ID local_authority=$LOCAL_ROW_ID mainnet_authority=$ACTIVATION_ROW_ID admitted_bindings=1/1/2 wallet_enablement_rows=0"
